    case .card(let value): try value.encode(to: encoder)
    case .followUp(let value): try value.encode(to: encoder)
    case .decision(let value): try value.encode(to: encoder)
    case .talk(let value): try value.encode(to: encoder)
    case .task(let value): try value.encode(to: encoder)
